#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# The executor's checks for one task, in one run; with --e2e also the end-to-end steps. Always
# stops what it started and confirms it.
#   ./scripts/orca/check.sh          test 
#   ./scripts/orca/check.sh --e2e    the same plus e2e 
# Prints one "=== <step> exit <code>" line per step and "CHECK OK" or "CHECK FAILED: <steps>".
# The full output goes to .scratch/tmp/check.log.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

e2e=0
case "${1:-}" in
  "") ;;
  --e2e) e2e=1 ;;
  *) echo "usage: scripts/orca/check.sh [--e2e]" >&2; exit 2 ;;
esac

mkdir -p .scratch/tmp
log=.scratch/tmp/check.log
: > "$log"
failed=()

step() {
  local name=$1 code
  shift
  echo "=== $name" >> "$log"
  "$@" >> "$log" 2>&1
  code=$?
  echo "=== $name exit $code"
  [ "$code" -eq 0 ] || failed+=("$name")
}

step test npm test
if [ "$e2e" -eq 1 ]; then
  step e2e npm run test:e2e
fi

echo "log: $log"
if [ "${#failed[@]}" -eq 0 ]; then
  echo "CHECK OK" | tee -a "$log"
else
  echo "CHECK FAILED: ${failed[*]}" | tee -a "$log"
  exit 1
fi
